def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    coord = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                w = min(1.0, max((1.35 - d / (r[i] + r[j])) / 0.35, 0.0))
                coord[i] += occ[j] * w
    weight = sum(occ[i] for i in range(n) if r[i] is not None and r[i] > 0)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n) if r[i] is not None and r[i] > 0) / weight
    if mean <= 1e-10:
        return 0.0
    variance = sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n) if r[i] is not None and r[i] > 0) / weight
    return variance / (mean * mean)

