    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and elements[i] == elements[j]:
            if r[i] is not None and r[i] > 0 and en[i] is not None and en[i] >= 2.0:
                compression = max(1.0 - d / (2.0 * r[i]), 0.0)
                total += occ[i] * occ[j] * compression * compression
    return total / (2.0 * weight)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    radii = []
    charges = []
    for site in sites:
        a = p.get(site.get('element')) or {}
        radii.append(a.get('covalent_radius_A'))
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = 0.0
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        charges.append(q)
    norms = [0.0 for a in sites]
    edges = []
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and charges[i] * charges[j] < 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                w = max(1.5 - d / (ri + rj), 0.0) ** 2
                if w > 0 and occ[i] > 0 and occ[j] > 0:
                    norms[i] += occ[j] * w
                    edges.append((i, j, w))
    compensation = [0.0 for a in sites]
    for i, j, w in edges:
        if norms[j] > 0:
            compensation[i] += occ[j] * w * charges[j] / norms[j]
    total = 0.0
    scale = 0.0
    for i in range(n):
        if charges[i] != 0 and radii[i] is not None and radii[i] > 0:
            total += occ[i] * abs(charges[i] + compensation[i])
            scale += occ[i] * abs(charges[i])
    return total / scale if scale > 0 else 0.0
